// Generated by AI (UnitTest MCP)
use crate::model::{declared_goal_in, referenced_nodes_in, referenced_tasks_in};
use crate::store::LodestarStore;
use crate::{
    decay, now_unix, Embedder, Knowledge, KnowledgeMatches, KnowledgeReach, Lodestar,
    LodestarError, Result, SignalPromotion,
};

/// Gating thresholds for consolidation (ADR-0005: don't launder coincidence).
const MIN_EVIDENCE_COUNT: usize = 3;
const MIN_EVIDENCE_SPAN_SECS: i64 = 3 * 24 * 3600; // proven across days, not one session

fn valid_memory_source_ref(source_ref: &str) -> bool {
    let relative = source_ref
        .strip_prefix("/memories/repo/")
        .or_else(|| source_ref.strip_prefix("/memories/session/"));
    relative.is_some_and(|relative| {
        !relative.is_empty()
            && !relative.contains('\\')
            && relative
                .split('/')
                .all(|segment| !segment.is_empty() && segment != "." && segment != "..")
    })
}

fn validated_retirement<'a>(actor: &'a str, reason: &'a str) -> Result<(&'a str, &'a str)> {
    let actor = actor.trim();
    if actor.is_empty() {
        return Err(LodestarError::Invalid(
            "retiring a lesson requires the person doing it".to_string(),
        ));
    }
    let reason = reason.trim();
    if reason.is_empty() {
        return Err(LodestarError::Invalid(
            "retiring a lesson requires a reason".to_string(),
        ));
    }
    Ok((actor, reason))
}

fn valid_repository_node(id: &str) -> bool {
    let Some(value) = id
        .strip_prefix("artifact:")
        .or_else(|| id.strip_prefix("symbol:"))
    else {
        return false;
    };
    !value.is_empty()
        && !value.starts_with('/')
        && !value.contains('\\')
        && value
            .as_bytes()
            .get(1)
            .is_none_or(|character| *character != b':')
        && !value.split('/').any(|segment| segment == "..")
}

impl Lodestar {
    pub fn record_knowledge(
        &self,
        statement: &str,
        evidence: &str,
        half_life_hours: Option<f64>,
    ) -> Result<Knowledge> {
        let hl = half_life_hours.unwrap_or(decay::KNOWLEDGE_DEFAULT_HALF_LIFE_HOURS);
        self.store
            .record_knowledge(statement, evidence, hl, now_unix())
    }

    /// Persist one reusable agent-memory lesson under a stable logical source.
    ///
    /// Lodestar accepts the portable virtual memory path supplied by the agent;
    /// it never reads editor-private storage. Global user memory is deliberately
    /// excluded from a repository database, and a sourced lesson must name the
    /// nodes or goal that can carry it to another agent.
    pub fn record_sourced_knowledge(
        &self,
        statement: &str,
        evidence: &str,
        half_life_hours: Option<f64>,
        source_ref: &str,
        actor: &str,
    ) -> Result<(Knowledge, Option<String>)> {
        let source_ref = source_ref.trim();
        if !valid_memory_source_ref(source_ref) {
            return Err(LodestarError::Invalid(
                "sourced knowledge accepts only /memories/repo/ or /memories/session/ paths"
                    .to_string(),
            ));
        }
        let actor = actor.trim();
        if actor.is_empty() {
            return Err(LodestarError::Invalid(
                "sourced knowledge requires the agent recording it".to_string(),
            ));
        }
        let nodes = referenced_nodes_in(evidence);
        if nodes.iter().any(|node| !valid_repository_node(node)) {
            return Err(LodestarError::Invalid(
                "sourced knowledge nodes must be repository-relative artifact: or symbol: ids"
                    .to_string(),
            ));
        }
        if !self.knowledge_reach_for_evidence(evidence)?.reaches() {
            return Err(LodestarError::Invalid(
                "sourced knowledge must reference artifact/symbol nodes, a goal, or a known task"
                    .to_string(),
            ));
        }
        let hl = half_life_hours.unwrap_or(decay::KNOWLEDGE_DEFAULT_HALF_LIFE_HOURS);
        self.store
            .record_sourced_knowledge(statement, evidence, hl, source_ref, actor, now_unix())
    }

    pub fn active_knowledge_for_source(&self, source_ref: &str) -> Result<Option<Knowledge>> {
        self.store.active_knowledge_for_source(source_ref.trim())
    }

    pub fn active_knowledge(&self) -> Result<Vec<Knowledge>> {
        self.store.active_knowledge(now_unix())
    }

    /// Active knowledge, ranked against a question instead of a spelling
    /// (ADR-0080).
    ///
    /// Knowledge was reachable only by exact substring, so a lesson found the
    /// agent who already knew which words it used and missed the one asking the
    /// question it answers. This sits behind the read every agent already
    /// performs rather than arriving as a new verb to remember.
    ///
    /// When `query` is given but no embedder is reachable it degrades to
    /// substring matching and **says so** in the returned mode: a silent
    /// downgrade would leave the caller believing an exact-match miss was a
    /// semantic one.
    pub fn search_knowledge(&self, query: &str) -> Result<KnowledgeMatches> {
        let now = now_unix();
        let active = self.store.active_knowledge(now)?;
        let embedder = Embedder::default();

        let degraded = |because: String| KnowledgeMatches {
            knowledge: LodestarStore::substring_knowledge(active.clone(), query),
            mode: "substring",
            degraded_because: Some(because),
            ranked: 0,
        };

        let query_vector = match embedder.embed(query) {
            Ok(vector) => vector,
            Err(e) => return Ok(degraded(e.to_string())),
        };
        // The index only ever filled on write, so a repository that learned
        // anything before it existed would search by substring forever. Warming
        // it here means the capability arrives with the upgrade, not with the
        // next lesson someone happens to record.
        self.store.backfill_embeddings(&active, &embedder, now);

        let (ranked, covered) =
            self.store
                .rank_knowledge(active.clone(), &query_vector, &embedder.model)?;
        if covered == 0 {
            return Ok(degraded(format!(
                "no knowledge could be embedded under model '{}'",
                embedder.model
            )));
        }
        Ok(KnowledgeMatches {
            knowledge: ranked,
            mode: "semantic",
            degraded_because: None,
            ranked: covered,
        })
    }

    pub fn reconfirm_knowledge(&self, id: &str) -> Result<bool> {
        self.store.reconfirm_knowledge(id, now_unix())
    }

    pub fn prune_knowledge(&self) -> Result<usize> {
        self.store.prune_knowledge(now_unix())
    }

    /// Retire a lesson explicitly, instead of waiting out its half-life.
    ///
    /// `prune_knowledge` removes what decayed; it cannot express "this is
    /// wrong" or "this was replaced". Until it could, a superseded record kept
    /// being counted and kept competing for the capped goal-advisory slots
    /// until its clock ran out, so `scripts/silent-knowledge.mjs` reported a
    /// backlog that doing the work could not reduce.
    ///
    /// Attributed and reasoned, like every other ending in this ledger: who,
    /// and why. Retiring is not deleting (ADR-0019) — the statement and its
    /// provenance stay readable, so a reader can still see what was believed.
    pub fn retire_knowledge(
        &self,
        id: &str,
        human: &str,
        reason: &str,
        superseded_by: Option<&str>,
    ) -> Result<Knowledge> {
        let (human, reason) = validated_retirement(human, reason)?;
        self.store
            .retire_knowledge(id, human, reason, superseded_by, now_unix())
    }

    /// Detach one memory source, retiring its lesson only when no source still
    /// carries it.
    pub fn retire_knowledge_source(
        &self,
        source_ref: &str,
        actor: &str,
        reason: &str,
    ) -> Result<(Knowledge, bool)> {
        let source_ref = source_ref.trim();
        if !valid_memory_source_ref(source_ref) {
            return Err(LodestarError::Invalid(
                "sourced knowledge accepts only /memories/repo/ or /memories/session/ paths"
                    .to_string(),
            ));
        }
        let (actor, reason) = validated_retirement(actor, reason)?;
        self.store
            .retire_knowledge_source(source_ref, actor, reason, now_unix())
    }

    /// How a recorded lesson can reach an agent, if it can at all.
    ///
    /// The advisory carries a lesson along two paths (see
    /// `facade::conformance::verdict`), and for a long time everything that
    /// *reported* reachability knew about only the first. `record_knowledge`
    /// answered `surfaces: !nodes.is_empty()`, `active_knowledge` said a
    /// node-less record "can never surface", and `scripts/silent-knowledge.mjs`
    /// counted 68 of 210 records unreachable when 12 were. All three were
    /// correct when written and were falsified by the same commit, because the
    /// rule lived in as many places as there were readers of it.
    ///
    /// So it lives here now, once, and the callers ask.
    pub fn knowledge_reach(&self, knowledge: &Knowledge) -> Result<KnowledgeReach> {
        self.knowledge_reach_for_evidence(&knowledge.evidence)
    }

    fn knowledge_reach_for_evidence(&self, evidence: &str) -> Result<KnowledgeReach> {
        if !referenced_nodes_in(evidence).is_empty() {
            return Ok(KnowledgeReach::ByNode);
        }
        if let Some(goal) = declared_goal_in(evidence) {
            return Ok(KnowledgeReach::ByGoal(goal));
        }
        for id in referenced_tasks_in(evidence) {
            // A lesson can name a task that has since been pruned; that is not
            // an error, it simply teaches us nothing about the goal.
            if let Some(task) = self.store.get_task(&id)? {
                return Ok(KnowledgeReach::ByGoal(task.goal_id));
            }
        }
        Ok(KnowledgeReach::Unreachable)
    }

    /// Gated promotion of a discovered regularity into durable knowledge. Returns
    /// `None` (and stores nothing) unless the evidence clears the count and span
    /// thresholds — signal, not coincidence (ADR-0005).
    pub fn consolidate(
        &self,
        statement: &str,
        evidence_node_ids: &[String],
        first_seen: i64,
        last_seen: i64,
    ) -> Result<Option<Knowledge>> {
        if evidence_node_ids.len() < MIN_EVIDENCE_COUNT
            || (last_seen - first_seen) < MIN_EVIDENCE_SPAN_SECS
        {
            return Ok(None);
        }
        let evidence = serde_json::json!({
            "nodes": evidence_node_ids,
            "count": evidence_node_ids.len(),
            "first_seen": first_seen,
            "last_seen": last_seen,
        })
        .to_string();
        let k = self.store.record_knowledge(
            statement,
            &evidence,
            decay::KNOWLEDGE_DEFAULT_HALF_LIFE_HOURS,
            now_unix(),
        )?;
        Ok(Some(k))
    }
}

/// The deterministic, model-free statement for a candidate that arrives without a
/// pre-distilled summary. Kept templated (not an LLM call) so promotion works with
/// no local model on any path (ADR-0022).
fn templated_statement(candidate: &SignalPromotion) -> String {
    format!(
        "proven regularity around {}: reinforced across {} corroborating signals",
        candidate.subject,
        candidate.evidence_node_ids.len()
    )
}

impl Lodestar {
    /// Promotion bridge (ADR-0022): feed MindLeak proven-signal candidates into the
    /// existing gated [`consolidate`](Self::consolidate). Reuses the count + span
    /// gate — it invents no new threshold, so same-session spam and one-offs are
    /// rejected exactly as today. Deterministic and model-optional: a candidate
    /// without a pre-distilled `statement` gets a templated one. Returns the
    /// candidates that cleared the gate and were stored.
    pub fn promote_signals(&self, candidates: &[SignalPromotion]) -> Result<Vec<Knowledge>> {
        let mut promoted = Vec::new();
        for candidate in candidates {
            let statement = candidate
                .statement
                .clone()
                .unwrap_or_else(|| templated_statement(candidate));
            if let Some(knowledge) = self.consolidate(
                &statement,
                &candidate.evidence_node_ids,
                candidate.first_seen,
                candidate.last_seen,
            )? {
                promoted.push(knowledge);
            }
        }
        Ok(promoted)
    }
}

#[cfg(test)]
mod tests {
    use crate::facade::test_support::engine;
    use crate::{GoalKind, KnowledgeReach, SignalPromotion};

    // Regression: a search that quietly degraded to substring matching was
    // indistinguishable from one that found nothing semantically, so a reader
    // would conclude the repository had never learned a lesson it holds - the
    // exact failure ADR-0080's second condition exists to prevent.
    #[test]
    fn a_search_without_an_embedder_says_it_answered_by_substring() {
        std::env::set_var("LODESTAR_EMBED_URL", "http://127.0.0.1:9");
        let e = engine();
        e.record_knowledge("never use --no-verify", "{}", None)
            .unwrap();

        let hit = e.search_knowledge("no-verify").unwrap();
        let miss = e.search_knowledge("how should I commit safely?").unwrap();

        assert_eq!(hit.mode, "substring");
        assert_eq!(hit.knowledge.len(), 1);
        assert!(hit.degraded_because.is_some());
        // The point of saying so: this question is answered by that lesson, and
        // substring matching cannot see it.
        assert!(miss.knowledge.is_empty());
        assert_eq!(miss.mode, "substring");
    }

    /// Every other ending in this ledger is attributed and reasoned, and this
    /// one is no different: a retirement nobody is recorded as making, for no
    /// stated reason, is the shape that leaves a reader unable to judge it.
    #[test]
    fn retiring_a_lesson_requires_who_and_why() {
        let e = engine();
        let k = e.record_knowledge("a lesson", "{}", None).unwrap();

        let anonymous = e
            .retire_knowledge(&k.id, "  ", "a reason", None)
            .unwrap_err();
        assert!(
            anonymous.to_string().contains("person doing it"),
            "{anonymous}"
        );

        let unexplained = e
            .retire_knowledge(&k.id, "Reviewer", " ", None)
            .unwrap_err();
        assert!(unexplained.to_string().contains("reason"), "{unexplained}");

        // Neither refusal retired it.
        assert_eq!(e.active_knowledge().unwrap().len(), 1);

        let retired = e
            .retire_knowledge(&k.id, "Reviewer", "replaced by a measurement", None)
            .unwrap();
        assert!(retired.retired());
        assert!(e.active_knowledge().unwrap().is_empty());
    }

    /// The nodes a lesson names carry it unconditionally, so that path wins
    /// even when the lesson also declares a goal.
    #[test]
    fn a_lesson_naming_nodes_reaches_by_node() {
        let e = engine();
        let k = e
            .record_knowledge(
                "about a file",
                r#"{"nodes":["artifact:src/a.rs"],"goal":"goal:anything"}"#,
                None,
            )
            .unwrap();

        assert_eq!(e.knowledge_reach(&k).unwrap(), KnowledgeReach::ByNode);
    }

    /// A lesson naming no node still reaches work under the goal it declares.
    ///
    /// This is the case every reader of reachability got wrong: `surfaces` was
    /// computed as `!nodes.is_empty()` in three places, so when the goal path
    /// landed all three began calling these records dead while they were
    /// arriving on every check under that goal.
    #[test]
    fn a_lesson_declaring_a_goal_reaches_that_goal() {
        let e = engine();
        let k = e
            .record_knowledge(
                "learned serving an objective",
                r#"{"goal":"goal:delivery"}"#,
                None,
            )
            .unwrap();

        assert_eq!(
            e.knowledge_reach(&k).unwrap(),
            KnowledgeReach::ByGoal("goal:delivery".to_string())
        );
    }

    /// Failing a declared goal, the goal of a task the lesson names will do —
    /// which is how most node-less records in a real ledger are placed, because
    /// agents cite the task they were working rather than the goal above it.
    #[test]
    fn a_lesson_naming_a_task_reaches_that_tasks_goal() {
        let e = engine();
        let goal = e
            .define_goal(
                GoalKind::Objective,
                "Delivery",
                "Work is delivered under this goal.",
                None,
            )
            .unwrap();
        let task = e
            .create_task(&goal.id, "some work", "done when done")
            .unwrap();
        let k = e
            .record_knowledge(
                "learned while doing it",
                &format!(r#"{{"task":"{}"}}"#, task.id),
                None,
            )
            .unwrap();

        assert_eq!(
            e.knowledge_reach(&k).unwrap(),
            KnowledgeReach::ByGoal(goal.id)
        );
    }

    /// A task the ledger no longer knows leaves the lesson unplaced. That is
    /// not an error — it simply teaches nothing about the goal — so it must
    /// report unreachable rather than fail the caller.
    #[test]
    fn a_lesson_naming_an_unknown_task_reaches_nobody() {
        let e = engine();
        let k = e
            .record_knowledge("cites a pruned task", r#"{"task":"task:deadbeef"}"#, None)
            .unwrap();

        assert_eq!(e.knowledge_reach(&k).unwrap(), KnowledgeReach::Unreachable);
        assert!(!e.knowledge_reach(&k).unwrap().reaches());
    }

    /// Evidence that is not JSON references nothing rather than throwing: it is
    /// free-form, and a record whose provenance never parsed is exactly the
    /// unreachable case the audit exists to find.
    #[test]
    fn unparseable_evidence_reaches_nobody_rather_than_failing() {
        let e = engine();
        let k = e
            .record_knowledge("recorded while pairing", "not json at all", None)
            .unwrap();

        assert_eq!(e.knowledge_reach(&k).unwrap(), KnowledgeReach::Unreachable);
    }

    #[test]
    fn sourced_memory_is_repo_or_session_scoped_and_must_reach_future_work() {
        let e = engine();
        let evidence = r#"{"nodes":["artifact:src/a.rs"]}"#;

        for source in [
            "/memories/preferences.md",
            "file:///private/memory.md",
            "/memories/repo/../preferences.md",
            "/memories/repo/",
        ] {
            let error = e
                .record_sourced_knowledge("a lesson", evidence, None, source, "agent-a")
                .unwrap_err();
            assert!(error.to_string().contains("/memories/repo/"), "{error}");
        }
        let unreachable = e
            .record_sourced_knowledge(
                "an unplaced lesson",
                "{}",
                None,
                "/memories/session/notes.md#lesson",
                "agent-a",
            )
            .unwrap_err();
        assert!(
            unreachable.to_string().contains("must reference"),
            "{unreachable}"
        );
        assert!(e.active_knowledge().unwrap().is_empty());

        for evidence in [
            r#"{"nodes":["src/a.rs"]}"#,
            r#"{"nodes":["artifact:C:/Users/name/private.rs"]}"#,
            r#"{"nodes":["artifact:../outside.rs"]}"#,
        ] {
            let error = e
                .record_sourced_knowledge(
                    "a misplaced lesson",
                    evidence,
                    None,
                    "/memories/repo/notes.md#misplaced",
                    "agent-a",
                )
                .unwrap_err();
            assert!(error.to_string().contains("repository-relative"), "{error}");
        }

        let (saved, replaced) = e
            .record_sourced_knowledge(
                "a placed lesson",
                evidence,
                None,
                "/memories/repo/notes.md#lesson",
                "agent-a",
            )
            .unwrap();
        assert_eq!(replaced, None);
        assert_eq!(
            e.active_knowledge_for_source("/memories/repo/notes.md#lesson")
                .unwrap()
                .unwrap()
                .id,
            saved.id
        );
    }

    #[test]
    fn sourced_memory_requires_an_attributed_agent() {
        let e = engine();
        let error = e
            .record_sourced_knowledge(
                "a lesson",
                r#"{"goal":"goal:delivery"}"#,
                None,
                "/memories/repo/notes.md#lesson",
                "  ",
            )
            .unwrap_err();

        assert!(error.to_string().contains("requires the agent"), "{error}");
        assert!(e.active_knowledge().unwrap().is_empty());
    }

    #[test]
    fn consolidation_gate_rejects_coincidence_and_accepts_proven_signal() {
        let e = engine();
        // Too few, too fast: not promoted.
        let weak = e
            .consolidate("X flakes", &["execution:1".into()], 0, 10)
            .unwrap();
        assert!(weak.is_none());

        // Enough evidence across a wide span: promoted.
        let strong = e
            .consolidate(
                "changes to X break Y",
                &[
                    "execution:1".into(),
                    "execution:2".into(),
                    "execution:3".into(),
                ],
                0,
                10 * 24 * 3600,
            )
            .unwrap();
        assert!(strong.is_some());
        assert_eq!(e.active_knowledge().unwrap().len(), 1);
    }

    #[test]
    fn promotion_bridge_reuses_the_gate_and_templates_statements() {
        let e = engine();
        // Too few / too fast: the shared count+span gate rejects it — no new
        // threshold, so coincidence is not laundered into knowledge.
        let weak = e
            .promote_signals(&[SignalPromotion {
                subject: "artifact:src/x.rs".into(),
                evidence_node_ids: vec!["execution:1".into()],
                first_seen: 0,
                last_seen: 10,
                statement: None,
            }])
            .unwrap();
        assert!(weak.is_empty());
        assert!(e.active_knowledge().unwrap().is_empty());

        // Proven across a wide span: promoted with a deterministic templated
        // statement (no model), and the evidence node ids retained for later
        // conformance intersection.
        let strong = e
            .promote_signals(&[SignalPromotion {
                subject: "artifact:src/x.rs".into(),
                evidence_node_ids: vec![
                    "execution:1".into(),
                    "execution:2".into(),
                    "execution:3".into(),
                ],
                first_seen: 0,
                last_seen: 10 * 24 * 3600,
                statement: None,
            }])
            .unwrap();
        assert_eq!(strong.len(), 1);
        assert!(strong[0].statement.contains("artifact:src/x.rs"));
        assert_eq!(
            strong[0].referenced_nodes(),
            vec!["execution:1", "execution:2", "execution:3"]
        );
        assert_eq!(e.active_knowledge().unwrap().len(), 1);
    }

    /// SPEC-CONSTITUTION §13: learned knowledge can *propose* policy but cannot
    /// *become* policy automatically.
    ///
    /// This holds by construction — knowledge and clauses are separate stores,
    /// and the only route into the constitution is an attributed human
    /// disposition. That is exactly why it is worth pinning: "true because
    /// nothing connects them" is the kind of property a later convenience
    /// (promote straight to a clause, adopt a proven regularity as a
    /// constraint) removes without anyone noticing it was load-bearing. A
    /// regularity observed across executions is evidence about what the code
    /// *does*; a clause states what it *must* do, and only a person may cross
    /// that line.
    #[test]
    fn proven_signal_becomes_knowledge_and_never_a_clause() {
        let e = engine();

        let promoted = e
            .promote_signals(&[SignalPromotion {
                subject: "artifact:src/x.rs".into(),
                evidence_node_ids: vec![
                    "execution:1".into(),
                    "execution:2".into(),
                    "execution:3".into(),
                ],
                first_seen: 0,
                last_seen: 10 * 24 * 3600,
                statement: None,
            }])
            .unwrap();

        assert_eq!(promoted.len(), 1, "the gate admitted the proven signal");
        assert_eq!(e.active_knowledge().unwrap().len(), 1);

        // The repository remains ungoverned: promotion created no constitution,
        // no version, and no clause of any status.
        assert!(
            e.get_constitution().unwrap().is_empty(),
            "promotion must not enrol a clause"
        );
        assert_eq!(
            e.constitution_status().unwrap().state,
            crate::ConstitutionState::Absent,
            "promotion must not constitute a project"
        );
    }
}
